import numpy as np
import hashlib

def evaluate_security_entropy(data: str) -> dict:
    sha = hashlib.sha256(data.encode()).hexdigest()
    entropy = -sum((p := data.count(c)/len(data)) * np.log2(p) for c in set(data))
    return {"sha256": sha, "shannon_entropy": round(entropy, 3)}

